    // Try alpha first
    const a = camera.alpha;
    camera.alpha = a + 1;
    if (camera.alpha !== a + 1) {
        // Was clamped, reset and try beta
        camera.alpha = a;
        const b = camera.beta;
        camera.beta = b + 1;
        if (camera.beta !== b + 1) {
            // Beta clamped too, try radius
            camera.beta = b;
            const r = camera.radius;
            camera.radius = r + 1;
            // This should work unless radius is at upper limit
            camera.radius = r;
        } else {
            camera.beta = b;
        }
    } else {
        camera.alpha = a;
    }
}
```

